implementation:
#include <linux/sem.h>
#include <linux/uaccess.h>

long sys_semtimedop(int semid, struct oabi_sembuf __user *tsops, unsigned nsops, const struct timespec __user *timeout) {
    struct oabi_sembuf *sops;
    struct timespec tspec;
    long ret = -EINVAL;

    if (nsops == 0) {
        return -EINVAL;
    }

    sops = kmalloc_array(nsops, sizeof(struct oabi_sembuf), GFP_KERNEL);
    if (!sops) {
        return -ENOMEM;
    }

    if (copy_from_user(sops, tsops, nsops * sizeof(struct oabi_sembuf))) {
        goto out_free;
    }

    if (timeout) {
        if (copy_from_user(&tspec, timeout, sizeof(struct timespec))) {
            goto out_free;
        }
        timeout = &tspec;
    }

    ret = do_semtimedop(semid, sops, nsops, timeout);

out_free:
    kfree(sops);
    return ret;
}
